from collections import defaultdict

def func(nums, k):
    d = defaultdict(int)
    for row in nums:
        for i in row:
            d[i] += 1
    temp = []
    for key, v in d.items():
        if len(temp) < k:
            temp.append((v, key))
            if len(temp) == k:
                heapq.heapify(temp)
        else:
            if v > temp[0][0]:
                heapq.heappop(temp)
                heapq.heappush(temp, (v, key))
    result = []
    while temp:
        v, key = heapq.heappop(temp)
        result.append(key)
    return result
```

