def newman_prime(n):
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0: return False
        return True

    def nsw(n):
        if n == 0: return 1
        if n == 1: return 1
        a, b = 1, 1
        for _ in range(2, n + 1):
            a, b = b, 2 * b + a
        return b

    count = 0
    i = 1
    while True:
        val = nsw(i)
        if is_prime(val):
            count += 1
            if count == n:
                return val
        i += 1
```

