def max_sum_increasing_subseq(arr, n, index, k):
    # msis[j] = max sum of an increasing subsequence ending at j, within prefix [0..index]
    msis = [arr[j] for j in range(n)]
    for i in range(index + 1):
        for j in range(i):
            if arr[i] > arr[j] and msis[j] + arr[i] > msis[i]:
                msis[i] = msis[j] + arr[i]

    # Extend a prefix subsequence ending at some j <= index with the kth element
    best = arr[k]
    for j in range(index + 1):
        if arr[j] < arr[k]:
            best = max(best, msis[j] + arr[k])
    return best
```

