def bell_number(n):
    # Bell triangle (Aitken's array) method
    if n == 0:
        return 1
    row = [1]
    for _ in range(n):
        new_row = [row[-1]]
        for val in row:
            new_row.append(new_row[-1] + val)
        row = new_row
    return row[0]
```

