def max_sum_increasing_subseq(arr, n, i, k):
    # Find max sum of increasing subsequence ending at or before i
    # where the last element is less than arr[k]
    dp = [x for x in arr[:i+1]]
    for idx in range(i + 1):
        for prev in range(idx):
            if arr[prev] < arr[idx]:
                dp[idx] = max(dp[idx], dp[prev] + arr[idx])

    max_prev = 0
    for idx in range(i + 1):
        if arr[idx] < arr[k]:
            max_prev = max(max_prev, dp[idx])

    return max_prev + arr[k]
```

